import json,glob
def maxrun(cmds):
    best=1;cur=1
    for i in range(1,len(cmds)):
        if cmds[i]==cmds[i-1]: cur+=1; best=max(best,cur)
        else: cur=1
    return best
for f in sorted(glob.glob('task_*.result.json')):
    d=json.load(open(f))
    t=d['task_id']
    try: m=json.load(open(t+'.messages.json'))
    except: continue
    cmds=[]
    for x in m:
        if x.get('role')=='assistant' and x.get('tool_calls'):
            for tc in x['tool_calls']:
                cmds.append(str(tc.get('function',{}).get('arguments','')))
    mr=maxrun(cmds)
